#include<iostream>
#include<vector>
using namespace std ;
class Solution {
public:
bool majEle(vector<int> & temp ,int target){
    int count=0;
    for(int val: temp){
      if( val==target){count++;}
    }
   if(count*2>temp.size()){
    return true ;
   }
   return false ;
}
   void subArray(vector<int>& nums , int start , int target , vector<int> temp,vector<vector<int>>& ans,int &count){
    if(start>=nums.size()){
        return ;
    }
      temp.push_back(nums[start]);

    if(majEle(temp, target)){
    	ans.push_back(temp);
        count+=1;
    }
        subArray(nums,start+1,target,temp,ans ,count);
        temp.pop_back();
    }
   
    vector<vector<int >> countMajoritySubarrays(vector<int>& nums, int target) {
        int count=0;
        vector<vector<int >> ans ;
       for(int i=0;i<nums.size();i++){
         vector<int>temp;
        subArray(nums,i, target,temp, ans ,count );
       }
    return ans;
    }
};
